class Solution {
    public int longestRun(int[] nums) {
        if (nums.length == 0) {
            return 0;
        }
        int best = 1;
        int current = 1;
        for (int i = 1; i < nums.length; i++) {
            if (Math.abs(nums[i] - nums[i - 1]) <= 1) {
                current++;
            } else {
                current = 1;
            }
            best = Math.max(best, current);
        }
        return best;
    }
}
